def _tpl(t):
    """A command template: {text:p1} marks a placeholder chip."""
    import re as _re
    ph = _re.findall(r'\{([^:{}]+):(p\d)\}', t)
    for i, _ in enumerate(ph): t = _re.sub(r'\{[^:{}]+:p\d\}', '⟦' + chr(97 + i) + '⟧', t, count=1)
    h = _sqlhl(t)
    for i, (w, c) in enumerate(ph): h = h.replace('⟦' + chr(97 + i) + '⟧', f'<span class="phd {c}">{w}</span>')
    return h
